package com.bank.square;

import java.util.*;
import java.util.logging.*;

public class SquareDemo {
    private static final Logger log = Logger.getLogger("Square");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> deviations = List.of(-3, 1, -2, 4, 0);
        SquareService service = new SquareService();

        log.info(() -> "Sorted squares: " + service.sortedSquares(deviations));
    }
}

// ─── Would be in service/SquareService.java ───
class SquareService {
    List<Long> sortedSquares(List<Integer> nums) {
        return nums.stream()
            .mapToLong(n -> (long) n * n)    // square (widen to long → no overflow)
            .sorted()                         // ascending by magnitude²
            .boxed()
            .toList();
    }
}
